def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        alive.append(opp)
        if opp.get('budget', 0) >= 120:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))

    if not alive:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    competitors = len(alive) + 1
    scarcity = competitors - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    must_win = False
    if hp <= 2:
        must_win = True
    if no_water_days >= 1 and hp <= 4:
        must_win = True
    if day >= 8 and hp <= 4:
        must_win = True

    if must_win:
        target = max(72.0, min(0.92 * budget, highest_prev + 6.0 if highest_prev > 0 else 78.0))
        return float(min(budget, target))

    if slots >= competitors:
        base = 8.0 + 2.0 * rich_opp
        if hp <= 4 or no_water_days >= 1:
            base += 10.0
        return float(min(budget, base))

    if scarcity >= 3:
        if hp >= 7 and no_water_days == 0:
            target = 18.0 + 4.0 * urgent_opp
        else:
            target = 58.0 + 4.0 * urgent_opp
            if highest_prev > 0:
                target = max(target, min(highest_prev + 2.0, 88.0))
        return float(min(budget, target))

    target = 32.0
    if avg_prev > 0:
        if highest_prev >= 150:
            target = 42.0 if hp >= 6 and no_water_days == 0 else 76.0
        elif highest_prev >= 100:
            target = 55.0 if hp <= 5 or no_water_days >= 1 else 38.0
        else:
            target = max(34.0, min(highest_prev + 2.0, 72.0))

    if hp <= 5:
        target += 12.0
    if no_water_days >= 1:
        target += 18.0
    if supply <= 16:
        target += 10.0
    elif supply >= 23:
        target -= 6.0

    reserve_floor = max(0.0, budget - DAILY_SALARY * max(0, 10 - day))
    if reserve_floor > 0:
        target = min(target, budget - reserve_floor * 0.35)

    target = max(6.0, target)
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # React to yesterday bids (only immediate trace)
    yesterday_bids = []
    yesterday_dead = 0
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass
        # If opponent died yesterday (final_hp < 0), they tended to bid aggressively
        # We infer from their previous_trace status/hp_after if present.
        status = prev.get('status', '')
        hp_after = prev.get('hp_after', None)
        if (isinstance(hp_after, (int, float)) and float(hp_after) < 0) or (isinstance(status, str) and 'dead' in status.lower()):
            yesterday_dead += 1

    # Baseline aggressiveness from supply pressure (more supply -> lower bid needed)
    # supply is between 15 and 25
    supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY + 1e-9)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Determine target bid level
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    # If we are in danger, bid higher; otherwise stay moderate to avoid budget burn.
    danger = (hp <= 2) or (no_water_days >= 2)

    # If others bid very high yesterday, they may be trying to secure water; bid slightly below the peak.
    peak_threshold = DAILY_SALARY * 0.85

    if danger:
        if highest_prev >= peak_threshold:
            target = min(budget, max(DAILY_SALARY * 0.75, highest_prev * 0.55))
        else:
            target = min(budget, DAILY_SALARY * (0.65 + 0.2 * (1.0 - supply_norm)))
    else:
        if highest_prev >= peak_threshold:
            # Avoid repeating their overbidding; bid around average or a bit above baseline.
            target = min(budget, max(DAILY_SALARY * 0.45, avg_prev * 0.55))
        else:
            target = min(budget, DAILY_SALARY * (0.48 + 0.18 * (1.0 - supply_norm)))

    # If we see any signs of yesterday deaths among opponents, slightly reduce to exploit potential budget exhaustion.
    if yesterday_dead > 0:
        target *= 0.92

    # Ensure at least a small competitive bid if budget allows
    min_reasonable = min(budget, DAILY_SALARY * 0.25)
    if target < min_reasonable:
        target = min_reasonable

    # Final cap
    if budget <= 0:
        return 0.0
    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.85

    if my_status['no_water_days'] > 0 or my_status['hp'] <= 3:
        base_bid = DAILY_SALARY * 1.25
    elif my_status['hp'] >= 8:
        base_bid = DAILY_SALARY * 0.75

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if my_status['no_water_days'] > 0 or my_status['hp'] <= 3:
            base_bid = max(base_bid, highest_prev_bid + 10)
        else:
            if highest_prev_bid >= DAILY_SALARY * 1.0:
                base_bid = max(base_bid, highest_prev_bid + 2)
            else:
                base_bid = max(base_bid, highest_prev_bid + 1)

    if day_context['day'] >= EPISODE_DAYS * 0.7:
        base_bid *= 1.05

    final_bid = min(my_status['budget'], base_bid)

    return max(1.0, final_bid)

